        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] cost = new long[n];
        for (int i = 0; i < n; i++) { in.nextToken(); cost[i] = (long) in.nval; }
